#!/usr/bin/env python3
"""Per-run, per-agent token usage from Workflow transcripts (read-only)."""
import json, glob, os, sys, collections, datetime

ROOT = '/root/.claude/projects/-home-user-fortress/fe616d40-a9c6-56d7-9da1-7168a172765d/subagents/workflows'
OUT = os.path.dirname(os.path.abspath(__file__))

def ts(s):
    return datetime.datetime.fromisoformat(s.replace('Z', '+00:00'))

rows = []
journals = {}
for d in sorted(glob.glob(ROOT + '/wf_*')):
    run = os.path.basename(d)
    started = collections.OrderedDict()
    order = []
    results = set(); failed = set(); other = []
    for i, line in enumerate(open(d + '/journal.jsonl')):
        try: j = json.loads(line)
        except Exception: continue
        t = j.get('type')
        if t == 'started':
            started.setdefault(j['agentId'], (j.get('label'), j.get('phase'), i))
            order.append(j['agentId'])
        elif t == 'result':
            results.add(j.get('agentId'))
        elif t == 'failed':
            failed.add(j.get('agentId')); other.append((i, t, j.get('agentId')))
        elif t != 'launched':
            other.append((i, t, j.get('agentId')))
    journals[run] = dict(order=order, results=sorted(results), failed=sorted(failed), other=other)
    for f in sorted(glob.glob(d + '/agent-*.jsonl')):
        aid = os.path.basename(f)[6:-6]
        meta = {}
        try: meta = json.load(open(f[:-6] + '.meta.json'))
        except Exception: pass
        label, phase, jline = started.get(aid, (meta.get('description'), meta.get('workflowPhase'), None))
        msgs = {}
        first = last = None
        tool_uses = 0
        models = collections.Counter()
        tool_ids = set()
        for line in open(f):
            try: j = json.loads(line)
            except Exception: continue
            t = j.get('timestamp')
            if t:
                if first is None or t < first: first = t
                if last is None or t > last: last = t
            if j.get('type') != 'assistant': continue
            m = j.get('message') or {}
            mid = m.get('id') or j.get('uuid')
            u = m.get('usage') or {}
            k = [u.get('input_tokens') or 0, u.get('cache_creation_input_tokens') or 0,
                 u.get('cache_read_input_tokens') or 0, u.get('output_tokens') or 0]
            cc = u.get('cache_creation') or {}
            k += [cc.get('ephemeral_5m_input_tokens') or 0, cc.get('ephemeral_1h_input_tokens') or 0]
            if mid in msgs:
                msgs[mid] = [max(a, b) for a, b in zip(msgs[mid], k)]
            else:
                msgs[mid] = k
                msgs[mid + '#model'] = m.get('model')
                msgs[mid + '#ts'] = t
            for c in (m.get('content') or []):
                if isinstance(c, dict) and c.get('type') == 'tool_use':
                    tool_ids.add(c.get('id'))
        ids = [k for k in msgs if '#' not in k]
        real = [k for k in ids if msgs[k + '#model'] != '<synthetic>']
        for k in real: models[msgs[k + '#model']] += 1
        s = [sum(msgs[k][i] for k in real) for i in range(6)]
        # final context at last real request (harness "tokens")
        lastk = max(real, key=lambda k: msgs[k + '#ts'] or '') if real else None
        finalctx = sum(msgs[lastk][:3]) if lastk else 0
        wall = (ts(last) - ts(first)).total_seconds() / 60 if first else 0
        rows.append(dict(run=run, agent=aid, label=label, phase=phase, jline=jline,
                         result=aid in results, failed=aid in failed,
                         calls=len(real), tools=len(tool_ids), inp=s[0], cw=s[1], cr=s[2], out=s[3],
                         cw5=s[4], cw1h=s[5], finalctx=finalctx,
                         first=first, last=last, wall=round(wall, 2),
                         models=dict(models), metamodel=meta.get('model')))

json.dump(dict(rows=rows, journals=journals), open(OUT + '/agents.json', 'w'), indent=0)
print(len(rows), 'agents')

